<script setup lang="ts">
import Icon from '../../shared/Icon.vue';
import {computed,ref,watch,onUnmounted} from 'vue';
import type {InfoFields} from '../../shared/api/meeting-info';
import type {Person,Category,Department} from '../../shared/api/meeting-options';
import type {InformationValidation} from '../minutes/final-information';
import type {CommandState} from '../../shared/composables/useCommand';
const props=defineProps<{validation?:InformationValidation|null;preventClose?:boolean;presentation?:'drawer'|'final';value:InfoFields;dirty:boolean;busy:boolean;blocked:boolean;state:CommandState;operation:string|null;conflict:boolean;conflictValue?:InfoFields|null;conflictToken?:string|null;canConfirm:boolean;categories:readonly Category[];people:readonly Person[];departments?:readonly Department[];peopleReady?:boolean;rosterNames?:Record<string,string>;rosterPeople?:Record<string,Person>;speakerBusy?:boolean;speakerMessage?:string|null;speakerError?:string|null;optionsBusy:boolean;optionsError:string|null;categoryMore:boolean;peopleMore:boolean;error:string|null;storageStatus:string}>();
const emit=defineEmits<{edit:[value:InfoFields];save:[];confirm:[];retry:[];reload:[];reapply:[];discard:[];search:[query:string,departmentId:string|null];directory:[open:boolean];directoryRetry:[];categories:[more:boolean];people:[query:string,departmentId:string|null];close:[];speakers:[]} >();
const formRoot=ref<HTMLElement>();
function focusField(field:InformationValidation['field']){const input=formRoot.value?.querySelector<HTMLElement>('[data-info-field="'+field+'"]');input?.scrollIntoView({block:'center'});input?.focus();}
defineExpose({focusField});
const query=ref(''),external=ref(''),institution=ref(''),department=ref(''),peopleTab=ref('internal'),peopleDialog=ref<HTMLDialogElement>(),selection=ref<string[]>([]),guests=ref<string[]>([]),selectionError=ref<string|null>(null);
const unresolved=computed(()=>['PREPARED','SENDING','UNCERTAIN','DENIED'].includes(props.state));
const departments=computed(()=>(props.departments??[]).filter(d=>d.active));
const visiblePeople=computed(()=>props.people.filter(p=>p.active));
let searchTimer:ReturnType<typeof setTimeout>|null=null;function search(){if(searchTimer)clearTimeout(searchTimer);searchTimer=null;emit('search',query.value,department.value||null);}
function selectDepartment(id:string){department.value=id;search();}
function closePeople(){if(searchTimer)clearTimeout(searchTimer);searchTimer=null;peopleDialog.value?.close();emit('directory',false);}
watch(query,()=>{if(searchTimer)clearTimeout(searchTimer);if(peopleDialog.value?.open)searchTimer=setTimeout(search,250);},{flush:'sync'});
onUnmounted(()=>{if(searchTimer)clearTimeout(searchTimer);emit('directory',false);});
function update(key:keyof InfoFields,value:unknown){emit('edit',{...props.value,[key]:value});}
function input(key:'name'|'summary'|'category'|'occurredOn',event:Event){const value=(event.target as HTMLInputElement).value;update(key,value===''?null:value);}
function personLabel(id:string){const p=props.rosterPeople?.[id]??props.people.find(p=>p.stableId===id);return (p?.displayName??props.rosterNames?.[id]??id)+' · '+(p?.department??'部门未提供');}
function openPeople(){peopleTab.value='internal';query.value='';selection.value=[...props.value.rosterDraftIds];guests.value=[...(props.value.externalRosterNames??[])];external.value='';institution.value='';selectionError.value=null;department.value='';peopleDialog.value?.showModal();emit('directory',true);search();}
function togglePerson(person:Person,event:Event){if(!person.active)return;selection.value=(event.target as HTMLInputElement).checked?[...new Set([...selection.value,person.stableId])]:selection.value.filter(id=>id!==person.stableId);}
function addExternal(){const name=external.value.trim(),org=institution.value.trim();if(!name||!org){selectionError.value='请填写外部人员姓名和机构';return false;}const label=name+' · '+org;if(!guests.value.includes(label))guests.value.push(label);external.value='';institution.value='';selectionError.value=null;return true;}
function submitPeople(){if((external.value.trim()||institution.value.trim())&&!addExternal())return;if(selection.value.length+guests.value.length>128){selectionError.value='参会人最多128人';return;}if(props.people.some(p=>selection.value.includes(p.stableId)&&!p.active)){selectionError.value='名单包含已停用人员，请移除后重试';return;}emit('edit',{...props.value,rosterDraftIds:[...selection.value],externalRosterNames:[...guests.value]});closePeople();}
</script>
<template>
 <section ref="formRoot" class="info-editor" :class="{'info-editor-final':presentation==='final'}" aria-labelledby="info-editor-heading">
  <h2 id="info-editor-heading">编辑会议信息</h2>

  <p v-if="blocked" role="alert">恢复记录暂无法读取，已暂停编辑和保存。请保持页面打开并重新加载。</p>
  <p v-if="storageStatus==='UNAVAILABLE'||storageStatus==='INVALID'" role="alert">本地恢复记录未保存，刷新或关闭页面可能丢失修改。</p>
  <p v-if="error" role="alert">{{error}}</p>
  <p v-if="unresolved" role="status">原操作结果尚未确认，请重试原请求。新操作需等待该结果。</p>
  <p v-if="state==='ACKNOWLEDGED'&&presentation!=='final'" role="status">已收到原操作成功回执，当前保存内容以重新读取的结果为准。</p>
  <p v-if="conflict" role="alert">服务器已有新版本。本地草稿已保留，请比较已保存信息后选择如何处理。</p>
  <section v-if="conflict&&conflictValue" class="conflict-preview" aria-label="最新保存版本">
   <h3>最新保存版本 · {{conflictToken}}</h3><dl><dt>会议名称</dt><dd>{{conflictValue.name??'未填写'}}</dd><dt>会议日期</dt><dd>{{conflictValue.occurredOn??'未填写'}}</dd><dt>会议分类</dt><dd>{{conflictValue.category??'未填写'}}</dd><dt>会议摘要</dt><dd>{{conflictValue.summary??'未填写'}}</dd><dt>最新名单草稿（企业身份）</dt><dd>{{conflictValue.rosterDraftIds.join('、')||'无'}}</dd><dt>最新外部人员草稿</dt><dd>{{(conflictValue.externalRosterNames??[]).join('、')||'无'}}</dd></dl>
  </section>
  <fieldset :disabled="blocked||busy||unresolved"><legend class="sr-only">会议信息与名单草稿</legend><div class="ac-info-fields">
   <div class="field"><label><span class="required">*</span>会议名称</label><input class="input" :aria-invalid="validation?.field==='name'||undefined" data-info-field="name" aria-required="true" aria-label="会议名称" placeholder="请输入会议名称，可在最终确认前补充" :value="value.name??''" @input="input('name',$event)"><p v-if="validation?.field==='name'" class="field-error" role="alert">{{validation.message}}</p><slot name="name-suggestion"/></div>
   <div class="field"><label>会议日期</label><input class="input" :aria-invalid="validation?.field==='occurredOn'||undefined" data-info-field="occurredOn" aria-label="会议日期" type="date" :value="value.occurredOn??''" @input="input('occurredOn',$event)"><p v-if="validation?.field==='occurredOn'" class="field-error" role="alert">{{validation.message}}</p></div>
   <div class="field"><label><span class="required">*</span>会议分类</label><select class="select" :aria-invalid="validation?.field==='category'||undefined" data-info-field="category" aria-required="true" aria-label="会议分类" :value="value.category??''" @change="input('category',$event)"><option value="">请选择会议分类</option><option v-if="value.category&&!categories.some(c=>c.id===value.category)" :value="value.category">{{value.category}}（已选）</option><option v-for="category in categories" :key="category.id" :value="category.id">{{category.label}}</option></select><button v-if="categoryMore" type="button" class="btn sm" :disabled="optionsBusy" @click="emit('categories',true)">更多会议分类</button><p v-if="validation?.field==='category'" class="field-error" role="alert">{{validation.message}}</p><slot name="category-suggestion"/></div>
   <div class="field"><label>会议摘要</label><textarea class="input" aria-label="会议摘要" placeholder="请输入会议摘要" rows="3" :value="value.summary??''" @input="input('summary',$event)"></textarea><slot name="summary-suggestion"/></div>
   <div class="field" :class="{'confirmation-participants-field':presentation==='final'}"><div class="ac-info-participant-title"><label>参会人</label><button type="button" class="btn sm ghost" @click="openPeople">添加参会人</button><button type="button" class="btn sm ghost" :disabled="speakerBusy" @click="emit('speakers')">{{speakerBusy?'读取发言人…':'从发言人获取'}}</button></div><div class="ac-participant-box" aria-label="已选参会人"><span v-if="!value.rosterDraftIds.length&&!value.externalRosterNames?.length" class="muted">暂未添加参会人</span><span v-for="id in value.rosterDraftIds" :key="id" class="ac-participant-tag" :title="id"><span>{{personLabel(id)}}</span><button type="button" :aria-label="'移除 '+id" @click="update('rosterDraftIds',value.rosterDraftIds.filter(x=>x!==id))"><Icon name="x" :size="12"/></button></span><span v-for="(name,index) in value.externalRosterNames??[]" :key="'guest-'+index" class="ac-participant-tag"><span>{{name}}</span><button type="button" :aria-label="'移除外部人员 '+name" @click="update('externalRosterNames',(value.externalRosterNames??[]).filter((_,i)=>i!==index))"><Icon name="x" :size="12"/></button></span></div><div class="hint">添加内部参会人，对方才可以查看会议记录；外部人员仅记录姓名和机构。</div><p v-if="speakerMessage" role="status">{{speakerMessage}}</p><p v-if="speakerError" role="alert">{{speakerError}}</p></div>
   <div v-if="presentation!=='final'&&canConfirm&&!dirty" class="roster-confirm"><p class="small muted">已保存的名单草稿尚待确认，确认后更新参会权限。</p><button type="button" class="btn" :disabled="busy||blocked||unresolved" @click="emit('confirm')">确认已保存名单</button></div>
   <dialog ref="peopleDialog" class="people-mask mask" role="presentation" @cancel.prevent="closePeople" @close="emit('directory',false)"><section class="people-dialog modal lg ac-people-modal" role="dialog" aria-modal="true" aria-labelledby="people-dialog-title"><header class="modal-h"><h3 id="people-dialog-title" class="m-t">添加参会人</h3><button type="button" class="m-x" aria-label="关闭人员选择" @click="closePeople"><Icon name="x" :size="18"/></button></header><div class="modal-b">
   <div class="ac-people-tabs" role="tablist" aria-label="人员类型"><button type="button" class="btn" role="tab" :class="{primary:peopleTab==='internal'}" :aria-selected="peopleTab==='internal'" @click="peopleTab='internal'">公司内部人员</button><button type="button" class="btn" role="tab" :class="{primary:peopleTab==='external'}" :aria-selected="peopleTab==='external'" @click="peopleTab='external'">外部人员</button></div>
   <section v-show="peopleTab==='internal'"><form class="directory-search" @submit.prevent="search"><input v-model="query" class="input ac-directory-search" aria-label="搜索企业人员" placeholder="搜索姓名、部门或企业身份"></form><div class="ac-directory-columns"><div class="ac-directory-depts" aria-label="部门"><button type="button" :class="{active:!department}" @click="selectDepartment('')">全部部门</button><button v-for="dept in departments" :key="dept.id" type="button" :class="{active:department===dept.id}" @click="selectDepartment(dept.id)">{{dept.name}}</button></div><div class="ac-directory-people"><label v-for="person in visiblePeople" :key="person.stableId" class="ac-directory-person" :title="person.stableId"><input type="checkbox" :checked="selection.includes(person.stableId)" :disabled="!person.active||optionsBusy" @change="togglePerson(person,$event)"><span><b>{{person.displayName}}</b><small>{{person.department??'部门未提供'}}</small></span></label><div v-if="!visiblePeople.length&&!optionsBusy&&!optionsError&&peopleReady!==false" class="empty">未找到人员</div><p v-if="optionsBusy" role="status">正在读取人员目录…</p><button v-if="peopleMore" type="button" class="btn" :disabled="optionsBusy" @click="emit('people',query,department||null)">下一页人员</button></div></div><div v-if="optionsError" role="alert"><p>{{optionsError}}</p><button type="button" class="btn sm" :disabled="optionsBusy" @click="emit('directoryRetry')">重新读取目录</button></div></section>
   <section v-show="peopleTab==='external'" class="ac-guest-form"><div class="field"><label><span class="ac-info-required">*</span>姓名</label><input v-model="external" class="input" aria-label="外部参会人员" placeholder="请输入外部人员姓名"></div><div class="field"><label><span class="ac-info-required">*</span>机构</label><input v-model="institution" class="input" aria-label="外部机构" placeholder="请输入所属机构"></div><button type="button" class="btn" @click="addExternal">加入待选名单</button><div class="ac-people-selection"><span v-for="(name,index) in guests" :key="index" class="ac-participant-tag"><span>{{name}}</span><button type="button" :aria-label="'移除待选外部人员 '+name" @click="guests.splice(index,1)"><Icon name="x" :size="12"/></button></span></div></section><p v-if="selectionError" role="alert">{{selectionError}}</p></div>
   <footer class="modal-f"><span class="small muted">已选 {{selection.length}} 名内部人员，{{guests.length}} 名其他人员</span><div class="flex"><button type="button" class="btn" @click="closePeople">取消</button><button type="button" class="btn primary" :disabled="optionsBusy" @click="submitPeople">添加所选人员</button></div></footer></section></dialog>
  </div></fieldset>
  <slot name="suggestions"/>
  <div v-if="presentation!=='final'" class="actions ac-info-drawer-footer"><button class="btn" :disabled="preventClose??(busy||blocked||unresolved)" @click="emit('close')">取消</button><button v-if="unresolved" class="btn primary" :disabled="busy||blocked" @click="emit('retry')">重试原请求</button><button v-else class="btn primary" :disabled="busy||blocked||conflict||state==='CONFLICT'||state==='REJECTED'" @click="emit('save')">保存</button></div>
  <div v-if="presentation==='final'&&unresolved" class="actions final-info-recovery"><button type="button" class="btn primary" :disabled="busy||blocked" @click="emit('retry')">重试原会议信息请求</button></div>
  <div v-if="conflict||state==='CONFLICT'||state==='REJECTED'" class="actions"><button v-if="conflict" class="btn" :disabled="busy||unresolved||blocked" @click="emit('reapply')">保留草稿并应用到最新版本</button><button class="btn" :disabled="busy||unresolved||blocked" @click="emit('discard')">放弃本地修改</button></div>
 </section>
</template>
<style scoped>
.info-editor h2{display:none}.info-editor{padding-bottom:76px}.info-editor fieldset{border:0;padding:0;min-width:0;margin:0}.ac-info-fields .field{margin-bottom:16px}.ac-info-fields .field:last-child{margin-bottom:0}.ac-info-fields .field>label{display:block}.required{color:var(--red);margin-right:4px}.ac-info-participant-title{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:8px}.ac-info-participant-title label{margin:0;font-size:13px;font-weight:600}.ac-participant-box{min-height:112px;display:flex;align-content:flex-start;align-items:flex-start;flex-wrap:wrap;gap:12px;border:1px solid #CCC;border-radius:4px;padding:16px 12px 12px}.ac-participant-tag{position:relative;display:inline-flex;align-items:center;gap:6px;max-width:100%;border-radius:4px;background:var(--orange-bg);color:var(--orange);padding:5px 18px 5px 8px;font-size:12px}.ac-participant-tag>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ac-participant-tag>button{position:absolute;right:-5px;top:-5px;width:16px;height:16px;border-radius:50%;background:#FFF;border:1px solid var(--border);display:flex;align-items:center;justify-content:center;padding:1px;cursor:pointer;color:inherit}.ac-info-fields .hint{line-height:1.8}.roster-confirm{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:12px 0;padding:12px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px}.roster-confirm p{margin:0}.ac-info-drawer-footer{position:absolute;bottom:0;left:0;right:0;display:flex;align-items:center;justify-content:flex-end;gap:10px;padding:16px 20px;background:white;border-top:1px solid var(--border);z-index:2;margin:0}.ac-info-drawer-footer .primary{order:5}.info-editor [role=alert]{margin:10px 0;color:#9a3412}.info-editor [role=status]{margin:8px 0;font-size:12px;color:var(--muted)}.people-dialog{margin:auto;width:760px;max-width:calc(100vw - 32px);max-height:86vh;padding:0;border:0;color:var(--text)}.people-mask{inset:0;width:auto;height:auto;max-width:none;max-height:none;margin:0;padding:0;border:0;color:var(--text);overflow:visible}.people-mask:not([open]){display:none}.people-mask::backdrop{background:transparent}.modal-h{display:flex;align-items:center;justify-content:space-between;padding:16px 22px;border-bottom:1px solid var(--border)}.modal-h h3{margin:0}.modal-b{padding:20px 22px;min-height:0}.modal-f{padding:14px 22px;display:flex;justify-content:space-between;gap:12px;border-top:1px solid var(--border)}.ac-people-tabs{display:flex;gap:8px;margin-bottom:14px}.directory-search{display:flex;gap:8px;margin:0}.ac-directory-search{flex:1;min-width:0}.ac-directory-columns{display:grid;grid-template-columns:30% minmax(0,1fr);border:1px solid var(--border);border-radius:4px;height:330px;overflow:hidden}.ac-directory-depts{overflow:auto;background:var(--bg);padding:8px;border-right:1px solid var(--border)}.ac-directory-depts button{width:100%;text-align:left;border:0;background:transparent;padding:10px 8px;color:var(--text);border-radius:4px;cursor:pointer;font:inherit;font-size:13px}.ac-directory-depts button.active{background:var(--orange-bg);color:var(--orange)}.ac-directory-people{overflow:auto;padding:6px 12px}.ac-directory-person{display:flex;align-items:center;gap:10px;padding:12px 4px;border-bottom:1px solid var(--border);cursor:pointer}.ac-directory-person small{display:block;color:var(--muted);margin-top:4px}.ac-directory-person input{accent-color:var(--orange)}.ac-directory-person>span{min-width:0;overflow-wrap:anywhere}.ac-guest-form .field{margin-bottom:14px}.ac-guest-form .input{width:100%}.ac-people-selection{max-height:100px;overflow:auto;display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.conflict-preview{padding:14px;background:#fff7ed}.conflict-preview dd{overflow-wrap:anywhere}.info-editor-final{padding-bottom:0}
@media(max-width:650px){.ac-directory-columns{grid-template-columns:34% minmax(0,1fr)}.modal-b{padding:16px}.modal-f{flex-wrap:wrap}.ac-info-participant-title{gap:6px}.ac-info-drawer-footer{padding:12px 16px}}
</style>

<style scoped>.info-editor-final .ac-info-fields .confirmation-participants-field{margin-bottom:0}</style>
